import { spawnSync } from "node:child_process";
const root = process.argv[1];
const baseline = spawnSync("git", ["-C", root + "/baseline-workspace", "diff", "--name-status"], { encoding: "utf8" });
const skill = spawnSync("git", ["-C", root + "/skill-workspace", "diff", "--name-status"], { encoding: "utf8" });
const baselineHead = spawnSync("git", ["-C", root + "/baseline-workspace", "rev-parse", "HEAD"], { encoding: "utf8" });
const skillHead = spawnSync("git", ["-C", root + "/skill-workspace", "rev-parse", "HEAD"], { encoding: "utf8" });
const expected = new Set(["AGENTS.md", "skills/architecture-decision/SKILL.md", "skills/architecture-decision/templates/adr.md", "skills/bounded-context-review/SKILL.md", "skills/bounded-context-review/templates/bounded-context-review.md", "skills/change-contract/SKILL.md", "skills/change-contract/templates/change-contract.md", "skills/domain-discovery/SKILL.md", "skills/domain-discovery/templates/domain-map.md", "skills/evidence-ledger/SKILL.md", "skills/evidence-ledger/templates/evidence-ledger.md", "skills/test-first-implementation/SKILL.md", "skills/test-first-implementation/templates/implementation-plan.md", "skills/using-extremely-hardcore/SKILL.md"]);
const changed = baseline.stdout.trim().split("\n").filter(Boolean).map((line) => line.slice(2));
const valid = baseline.status === 0 && skill.status === 0 && baselineHead.stdout.trim() === skillHead.stdout.trim() && changed.length === expected.size && changed.every((path) => expected.has(path)) && skill.stdout === "";
if (!valid) process.exit(1);
console.log(JSON.stringify({ commit: baselineHead.stdout.trim(), baselineRemovedPaths: changed.length, skillWorkspaceClean: true }));
